"the Living Room": "phòng khách",
"Kitchen": "Nhà bếp",
"the Kitchen": "nhà bếp",
"Study": "Phòng làm việc",
"the Study": "phòng làm việc",
"Balcony": "Ban công",
"the Balcony": "ban công",
"Your Corner": "Góc của bạn",
"Bedroom": "Phòng ngủ",
"the Bedroom": "phòng ngủ",
